typedef unsigned int size_t;
extern "C" size_t strlen(const char *);

class stringx {
public:
  void *data;
  stringx();
  stringx(const stringx&);
  ~stringx();
  void make_room(int);
  void append(const stringx&);
  void append(const char *, int);
};

inline stringx operator+(const stringx& a, const char *b)
{
  stringx result;
  int n = strlen(b);
  result.make_room(((int *)a.data)[2] + n);
  result.append(a);
  result.append(b, n);
  return result;
}

inline stringx operator+(const stringx& a, const stringx& b)
{
  stringx result;
  result.make_room(((int *)a.data)[2] + ((int *)b.data)[2]);
  result.append(a);
  result.append(b);
  return result;
}

class script_instance { public: void *vptr; stringx name; const stringx& get_name() const { return name; } };
class script_executable { public: void *vptr; stringx fullname; const stringx& get_fullname() const { return fullname; } };
class vm_thread { public: void *vptr; script_instance *instance; script_executable *executable; script_instance *get_instance() { return instance; } script_executable *get_executable() { return executable; } };
class vm_stack { public: char pad[12]; vm_thread *thread; bool push(const char *, int); vm_thread *get_thread() { return thread; } };
struct vector3d { float x, y, z; };
extern vector3d script_bsp_hit_pos;
extern void error(const stringx&);

extern "C" bool candidate(void *, vm_stack& stack, int) __asm__("__cl__27slf_get_bsp_check_hit_pos_tR8vm_stackQ320script_library_class8function7entry_t");
bool candidate(void *, vm_stack& stack, int)
{
  vector3d result = script_bsp_hit_pos;
  if (!stack.push((char*)&result, sizeof(result)))
    error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname());
  return true;
}
